import json
from pathlib import Path
from collections import Counter

import numpy as np
import pandas as pd


# Location of the JSON logs generated by Cowrie
LOG_FILE = (
    Path.home()
    / "adaptive-honeypot"
    / "cowrie-lab"
    / "var"
    / "log"
    / "cowrie"
    / "cowrie.json"
)

REPORT_DIR = Path.home() / "adaptive-honeypot" / "reports"


def load_logs():
    """Read Cowrie's JSON-lines log file."""
    if not LOG_FILE.exists():
        print(f"[ERROR] Log file not found: {LOG_FILE}")
        return []

    events = []

    with LOG_FILE.open("r", encoding="utf-8") as file:
        for line_number, line in enumerate(file, start=1):
            try:
                event = json.loads(line)
                events.append(event)
            except json.JSONDecodeError:
                print(f"[WARNING] Skipping invalid JSON on line {line_number}")

    return events


def analyse_events(events):
    """Summarise events and calculate preliminary activity scores."""
    if not events:
        print("[INFO] No events available to analyse.")
        return

    df = pd.DataFrame(events)

    event_counts = Counter(
        df["eventid"].dropna()
        if "eventid" in df.columns
        else []
    )

    # Preliminary rule-based scores, not proof of a real attack.
    weights = {
        "cowrie.login.failed": 15,
        "cowrie.login.success": 5,
        "cowrie.command.input": 3,
    }

    if "src_ip" in df.columns:
        ip_scores = {}

        for ip, group in df.groupby("src_ip"):
            score = sum(
                weights.get(event_id, 0)
                for event_id in group.get("eventid", [])
            )

            # Keep the score within a 0-100 range.
            ip_scores[ip] = int(np.clip(score, 0, 100))

        print("\nPreliminary activity scores by source IP:")
        for ip, score in sorted(
            ip_scores.items(), key=lambda item: item[1], reverse=True
        ):
            print(f"  {ip}: {score}/100")
    else:
        ip_scores = {}

    print("\nEvent summary:")
    for event_id, count in event_counts.most_common():
        print(f"  {event_id}: {count}")

    print(f"\nTotal events: {len(df)}")

    if "src_ip" in df.columns:
        print(f"Unique source IPs: {df['src_ip'].nunique()}")

    if "username" in df.columns:
        usernames = (
            df["username"]
            .dropna()
            .value_counts()
            .head(10)
        )
        if not usernames.empty:
            print("\nMost frequently recorded usernames:")
            for username, count in usernames.items():
                print(f"  {username}: {count}")

    if "input" in df.columns:
        commands = (
            df.loc[df["eventid"] == "cowrie.command.input", "input"]
            .dropna()
            .value_counts()
            .head(10)
        )
        if not commands.empty:
            print("\nMost frequently recorded commands:")
            for command, count in commands.items():
                print(f"  {command}: {count}")

    REPORT_DIR.mkdir(parents=True, exist_ok=True)

    csv_path = REPORT_DIR / "cowrie_events.csv"
    df.to_csv(csv_path, index=False)

    summary_path = REPORT_DIR / "analysis_summary.txt"
    with summary_path.open("w", encoding="utf-8") as report:
        report.write("COWRIE LOG ANALYSIS REPORT\n")
        report.write("=========================\n\n")
        report.write(f"Total events: {len(df)}\n")
        report.write(f"Unique source IPs: {df['src_ip'].nunique() if 'src_ip' in df.columns else 0}\n\n")
        report.write("Event counts:\n")

        for event_id, count in event_counts.most_common():
            report.write(f"{event_id}: {count}\n")

        report.write("\nPreliminary activity scores:\n")
        for ip, score in sorted(
            ip_scores.items(), key=lambda item: item[1], reverse=True
        ):
            report.write(f"{ip}: {score}/100\n")

        report.write(
            "\nNote: Scores are preliminary rule-based indicators. "
            "They do not establish that an IP is malicious.\n"
        )

    print(f"\nCSV report saved to: {csv_path}")
    print(f"Summary report saved to: {summary_path}")


if __name__ == "__main__":
    print("=== Cowrie Log Analyser ===")
    print(f"Reading logs from: {LOG_FILE}")

    recorded_events = load_logs()
    analyse_events(recorded_events)
